// The spectral library: spectra imported from library files.
export class Library {
  constructor() {
    this.spectra = [];
  }

  // Importing a file again replaces its earlier spectra.
  import(fileName, spectra) {
    this.spectra = this.spectra.filter((s) => s.source !== fileName);
    for (const spectrum of spectra) this.spectra.push({ ...spectrum, source: fileName });
    return spectra.length;
  }

  bySource(fileName) {
    return this.spectra.filter((s) => s.source === fileName);
  }
}

