import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Library } from '../src/library.js';

test('importing a file again replaces its spectra and keeps the others', () => {
  const library = new Library();
  library.import('rocks.txt', [{ name: 'basalt' }, { name: 'granite' }]);
  library.import('leaves.txt', [{ name: 'oak' }]);
  library.import('rocks.txt', [{ name: 'basalt' }]);
  assert.deepEqual(library.bySource('rocks.txt').map((s) => s.name), ['basalt']);
  assert.equal(library.spectra.length, 2);
});
